python3 -c 'import json,sys;P=[2];p=lambda i:([P.append(next(n for n in range(P[-1]+1,10**6) if all(n%d for d in P if d*d<=n))) for _ in range(max(0,i+1-len(P)))],P[i])[1];E=lambda a:__import__("math").prod(p(i)**(x+1) for i,x in enumerate(a));Z=lambda x:2*x if x>=0 else -2*x-1;U=lambda x:x//2 if x%2==0 else -(x+1)//2;G=lambda a:E([a[0],Z(a[1]),Z(a[2]),a[3]]);t=int(sys.argv[1]) if len(sys.argv)>1 else 100;s=[[22,i,t,d] for i,d in zip((0,1,2),(3,0,0))];assertion=lambda a:len(a)==3 and len({x[0] for x in a})==1 and len({x[1] for x in a})==3 and len({x[2] for x in a})==1 and sum(x[3] for x in a)==3;assert assertion(s);h=[x[:] for x in s];[x.__setitem__(3,1) for x in s];assert assertion(s) and all(x[3]==1 for x in s);print(json.dumps({"fixed_point":True,"same_worldline_by_axiom":True,"encounters":s,"godel":[str(G(x)) for x in s],"initial":h},separators=(",",":")))'
